package dev.bossestesting.registry;

import com.mojang.serialization.MapCodec;
import dev.bossestesting.BossesTesting;
import net.minecraft.core.particles.ColorParticleOption;
import net.minecraft.core.particles.ParticleType;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

/**
 * Own particles with own spritesheets (textures/particle/ember_*.png, smoke_*.png, generated by tools/gerar_assets.py),
 * tinted by a {@link ColorParticleOption}: orange in phase 1, cyan and red in phase 2. Sent by the server with
 * {@code ServerLevel.sendParticles} (one vanilla packet per call), drawn by {@code client.particle}.
 */
public final class ModParticles {
    public static final DeferredRegister<ParticleType<?>> REGISTER = DeferredRegister.create(Registries.PARTICLE_TYPE, BossesTesting.MODID);

    /** Hot ember / spark: bright, gravity, stretched along its velocity. */
    public static final DeferredHolder<ParticleType<?>, ParticleType<ColorParticleOption>> EMBER = REGISTER.register("ember", ModParticles::colored);
    /** Thick rolling smoke puff that grows and darkens. */
    public static final DeferredHolder<ParticleType<?>, ParticleType<ColorParticleOption>> SMOKE = REGISTER.register("smoke", ModParticles::colored);
    /** Electric discharge flicker (short-lived, fullbright). */
    public static final DeferredHolder<ParticleType<?>, ParticleType<ColorParticleOption>> ARC = REGISTER.register("arc", ModParticles::colored);

    private static ParticleType<ColorParticleOption> colored() {
        return new ParticleType<>(true) {
            @Override public MapCodec<ColorParticleOption> codec() { return ColorParticleOption.codec(this); }
            @Override public StreamCodec<? super RegistryFriendlyByteBuf, ColorParticleOption> streamCodec() { return ColorParticleOption.streamCodec(this); }
        };
    }

    private ModParticles() {}
}
